@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Outfit:wght@400;500;600;700;800&display=swap');
:root{--ink:#f7f6ff;--muted:#989bb7;--panel:#171b30;--line:rgba(195,197,255,.12);--pink:#ff78b9;--cyan:#73e8ff;--gold:#ffcf74;--violet:#b59aff}*{box-sizing:border-box}body{margin:0;background:#101322;color:var(--ink);font-family:Outfit,system-ui,sans-serif;min-height:100vh;overflow:hidden}button{font:inherit;color:inherit;cursor:pointer;border:0}#app{height:100dvh;min-height:620px;display:grid;grid-template-rows:66px 1fr 112px;background:radial-gradient(ellipse at 52% 32%,#252a49 0,#15182b 52%,#101322 100%);position:relative;overflow:hidden}.topbar{display:flex;align-items:center;padding:0 24px;border-bottom:1px solid var(--line);background:#0e111fbd;z-index:3;gap:22px}.brand{display:flex;align-items:center;gap:11px;min-width:220px}.brand-mark{width:34px;height:34px;border-radius:11px;background:linear-gradient(145deg,#ff96c7,#9e72ff 72%);display:grid;place-items:center;box-shadow:0 0 24px #b26fff55;font-size:19px}.brand-name{font-weight:800;letter-spacing:2px;font-size:15px}.brand-sub{font-size:9px;color:#a6a8c0;letter-spacing:2.1px;margin-top:1px}.level-pill{border-left:1px solid var(--line);padding-left:22px;font-size:12px;color:#c1c3d7}.level-pill b{color:#fff}.top-spacer{flex:1}.resource{display:flex;align-items:center;gap:8px;font-size:13px;font-weight:700;padding:8px 13px;border:1px solid var(--line);border-radius:11px;background:#ffffff06}.resource i{font-style:normal;font-size:17px;color:var(--gold)}.resource:nth-last-of-type(2) i{color:var(--pink)}.resource small{font:9px 'DM Mono';color:var(--muted);margin-left:3px;letter-spacing:.5px}.sound{width:36px;height:36px;border-radius:10px;background:#ffffff0b;border:1px solid var(--line)}.main{display:grid;grid-template-columns:minmax(0,1fr) 294px;min-height:0;padding:16px 18px 12px;gap:14px}.game-wrap{position:relative;min-width:0;overflow:hidden;border:1px solid #c5c6ff20;border-radius:17px;background:#1a2037;box-shadow:0 16px 55px #0004}canvas{width:100%;height:100%;display:block}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#14182a99,transparent 30%,transparent 73%,#14182a66)}.scene-title{position:absolute;left:25px;top:21px;pointer-events:none;text-shadow:0 2px 14px #14172a}.eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.55px;color:#aeb3d2}.scene-title .eyebrow{color:#e2a8ff}.scene-title h1{font-size:25px;letter-spacing:-.7px;margin:6px 0 1px}.scene-title p{font-size:11px;color:#c0c2d4;margin:0}.scene-tag{position:absolute;right:19px;top:20px;border:1px solid #c5c6ff25;background:#15192dcc;padding:8px 11px;border-radius:9px;color:#d4d7ed;font:9px 'DM Mono';letter-spacing:.8px;display:flex;align-items:center;gap:7px}.live-dot{height:6px;width:6px;border-radius:50%;background:#7cf1c0;box-shadow:0 0 9px #7cf1c0}.wave-card{position:absolute;right:18px;top:68px;width:170px;padding:12px 13px;border:1px solid #c5c6ff22;border-radius:12px;background:#15192ddd;backdrop-filter:blur(8px)}.wave-top,.wave-foot{display:flex;align-items:center;justify-content:space-between}.wave-top{font:11px 'DM Mono';color:#dedff2}.wave-top b{font-size:16px;color:#fff}.wave-top small{font-size:10px;color:#8f93ad}.wave-status{font-size:8px!important;color:#79e8d1!important;letter-spacing:1px}.wave-track{height:4px;background:#ffffff13;border-radius:5px;margin:9px 0;overflow:hidden}.wave-track i{height:100%;width:0;display:block;background:linear-gradient(90deg,#b084ff,#ff88c7);transition:width .3s}.wave-foot{font:8px 'DM Mono';color:#999db8}.wave-foot span:last-child{color:var(--gold)}.canvas-hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;padding:8px 12px;border-radius:8px;background:#111426b8;border:1px solid #ffffff12;font:8px 'DM Mono';letter-spacing:1px;color:#b9bdd5;pointer-events:none}.toast{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);padding:10px 15px;border-radius:11px;background:#121629ee;border:1px solid #b795ff55;font-size:12px;opacity:0;transition:.25s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1}.side-panel{padding:18px 17px;border-radius:16px;background:linear-gradient(155deg,#1b2038,#171a2d);border:1px solid var(--line);display:flex;flex-direction:column;min-height:0}.side-heading{display:flex;align-items:center;justify-content:space-between}.side-heading h2{margin:3px 0 0;font-size:19px;letter-spacing:-.4px}.unit-count{text-align:right;font:8px 'DM Mono';letter-spacing:.7px;color:#999db7}.unit-count b{display:block;color:#fff;font:700 17px Outfit}.side-intro{font-size:10px;line-height:1.5;color:#a2a5bd;margin:9px 0 12px}.unit-list{display:flex;flex-direction:column;gap:7px}.unit-card{display:flex;align-items:center;gap:10px;padding:9px 10px;border:1px solid #ffffff12;border-radius:11px;background:#ffffff04;text-align:left;transition:.18s;width:100%}.unit-card:hover,.unit-card.selected{background:#b18aff13;border-color:#bc99ff77;transform:translateY(-1px)}.unit-icon{width:36px;height:36px;display:grid;place-items:center;border-radius:10px;font-size:21px;flex-shrink:0}.unit-info{flex:1;min-width:0}.unit-info b{font-size:11px;display:block}.unit-info small{font-size:8px;color:#989bb4}.unit-cost{font:10px 'DM Mono';color:var(--gold);white-space:nowrap}.divider{height:1px;background:var(--line);margin:14px 0}.objectives-heading h2{font-size:16px}.mission-icon{color:#c8a4ff;font-size:18px}.objective{display:flex;align-items:center;gap:9px;margin-top:13px}.objective-check{width:20px;height:20px;display:grid;place-items:center;border-radius:7px;background:#82f0c21c;color:#80edc1;font-size:11px}.objective-check.dim{background:#c5a1ff18;color:#c3a0ff}.objective b{display:block;font-size:10px}.objective small{display:block;color:#9296b0;font-size:8px;margin-top:2px}.side-bottom{margin-top:auto;padding:10px 11px;border:1px solid #bc99ff21;background:#b18aff09;border-radius:10px;display:flex;gap:9px;align-items:flex-start}.tip-icon{font-size:16px;color:#d5a9ff}.side-bottom p{margin:0;font-size:9px;line-height:1.5;color:#a9acc2}.side-bottom b{color:#e7dafa}.bottom{display:flex;align-items:center;padding:12px 20px 15px;border-top:1px solid var(--line);background:#111425e8;gap:17px;z-index:2}.footer-label{min-width:145px}.footer-label b{display:block;font-size:12px;margin-top:5px}.cards{display:flex;gap:9px;flex:1;min-width:0}.pick-card{position:relative;height:77px;min-width:114px;flex:1;max-width:170px;border:1px solid #ffffff14;background:#ffffff05;border-radius:12px;text-align:left;padding:9px 10px;transition:.18s;overflow:hidden}.pick-card:hover,.pick-card.active{transform:translateY(-2px);border-color:#bd98ff8c;background:#b18aff12}.pick-card.active:after{content:'SELECTED';position:absolute;right:7px;top:7px;font:7px 'DM Mono';color:#dbb9ff;letter-spacing:.5px}.pick-top{display:flex;align-items:center;gap:7px}.pick-emoji{font-size:21px}.pick-name{font-size:10px;font-weight:700}.pick-role{font-size:8px;color:#989bb7}.pick-cost{position:absolute;right:9px;bottom:8px;font:9px 'DM Mono';color:var(--gold)}.pick-stats{position:absolute;left:10px;bottom:8px;font:7px 'DM Mono';color:#868ba8}.footer-actions{display:flex;align-items:center;gap:8px}.mode-btn{height:44px;padding:0 11px;border:1px solid #bd98ff53;background:#b18aff10;border-radius:11px;color:#d3b6ff;font-size:17px;white-space:nowrap}.mode-btn span{font-size:8px;letter-spacing:.8px;margin-left:4px}.launch-btn{height:48px;min-width:142px;border-radius:11px;background:linear-gradient(110deg,#bc79fa,#e781c0);box-shadow:0 5px 20px #bf73ed30;display:grid;grid-template-columns:16px auto;grid-template-rows:1fr 1fr;align-items:center;padding:7px 12px;text-align:left;transition:.15s}.launch-btn:hover{filter:brightness(1.1);transform:translateY(-1px)}.launch-btn span{grid-row:1/3;font-size:12px}.launch-btn b{font-size:10px;letter-spacing:.5px}.launch-btn small{font:7px 'DM Mono';opacity:.78}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#0a0c18c9;backdrop-filter:blur(9px);display:grid;place-items:center;padding:18px;opacity:0;visibility:hidden;transition:.3s}.modal-backdrop.open{opacity:1;visibility:visible}.modal{position:relative;width:min(410px,100%);padding:33px 33px 28px;border:1px solid #c49aff4a;border-radius:20px;background:radial-gradient(ellipse at 50% 0,#3b2859,#191d32 62%);text-align:center;box-shadow:0 25px 90px #0009}.modal-close{position:absolute;right:13px;top:10px;background:none;color:#a8acc2;font-size:23px}.modal-star{margin:0 auto 15px;width:52px;height:52px;border-radius:16px;background:linear-gradient(145deg,#ff96c7,#9e72ff);display:grid;place-items:center;font-size:27px;box-shadow:0 0 32px #c27fff66}.modal h2{font-size:25px;margin:7px 0 8px;letter-spacing:-.5px}.modal p{font-size:12px;line-height:1.65;color:#adb0c8;margin:0 auto 22px;max-width:310px}.modal-buttons{display:flex;justify-content:center;gap:9px}.modal-buttons button{padding:11px 17px;border-radius:10px;background:linear-gradient(110deg,#bc79fa,#e781c0);font-weight:700;font-size:11px}.modal-buttons .secondary{background:#ffffff0b;border:1px solid #ffffff1b}.hidden{display:none!important}
@media(max-width:900px){#app{grid-template-rows:58px 1fr 105px}.topbar{padding:0 12px;gap:10px}.brand{min-width:0}.brand-sub{display:none}.level-pill{padding-left:10px;font-size:10px}.main{grid-template-columns:minmax(0,1fr) 245px;padding:10px;gap:9px}.side-panel{padding:13px}.unit-card{padding:7px}.bottom{padding:9px;gap:9px}.footer-label{min-width:105px}.pick-card{min-width:95px}.mode-btn{height:40px;padding:0 8px}.launch-btn{min-width:126px}}
@media(max-width:650px){body{overflow:auto}#app{height:100dvh;min-height:560px;grid-template-rows:54px minmax(0,1fr) 154px}.topbar{padding:0 9px;gap:7px}.brand-mark{width:29px;height:29px;border-radius:9px}.brand-name{font-size:12px}.level-pill{font-size:8px;border:0;padding:0;margin-left:4px}.resource{padding:6px 7px;gap:5px;font-size:11px}.resource small{display:none}.sound{height:31px;width:31px}.main{grid-template-columns:1fr;padding:8px;position:relative}.game-wrap{min-height:300px}.side-panel{position:absolute;right:8px;top:8px;width:145px;max-height:calc(100% - 16px);padding:9px;background:#171b30ed;z-index:2;overflow:auto}.side-heading h2{font-size:15px}.side-intro,.divider,.objectives-heading,.objective,.side-bottom{display:none}.unit-card{gap:5px;padding:6px}.unit-icon{width:27px;height:27px;font-size:16px}.unit-info b{font-size:9px}.unit-info small{font-size:7px}.unit-cost{font-size:8px}.unit-list{gap:4px}.unit-count span{font-size:6px}.unit-count b{font-size:13px}.scene-title{left:12px;top:12px}.scene-title h1{font-size:19px}.scene-title p{font-size:9px;max-width:190px}.scene-tag{top:12px;right:9px;padding:6px;font-size:7px}.wave-card{top:auto;bottom:43px;right:9px;width:135px;padding:8px}.canvas-hint{bottom:11px;left:10px;transform:none;font-size:7px}.bottom{display:grid;grid-template-columns:1fr auto;grid-template-rows:23px 1fr;padding:7px 9px 9px;gap:5px}.footer-label{min-width:0}.footer-label .eyebrow{font-size:7px}.footer-label b{display:inline;font-size:10px;margin-left:5px}.cards{grid-column:1/3;grid-row:2;overflow-x:auto;gap:6px;padding:1px 0 3px}.pick-card{height:70px;min-width:104px;flex:none}.footer-actions{grid-column:2;grid-row:1;gap:5px}.mode-btn{height:28px;font-size:13px;border-radius:8px}.mode-btn span{font-size:7px}.launch-btn{height:31px;min-width:100px;padding:4px 7px;border-radius:8px;grid-template-columns:12px auto}.launch-btn b{font-size:8px}.launch-btn small{font-size:6px}.launch-btn span{font-size:9px}.modal{padding:28px 20px 22px}}

(()=>{
const $=s=>document.querySelector(s), canvas=$('#game'),ctx=canvas.getContext('2d');
const units=[{id:'mira',name:'Mira',role:'Star Archer',emoji:'🏹',cost:90,color:'#8eeaff',range:2.9,damage:16,rate:.82,desc:'Long range · balanced',stats:'RANGE 3  ·  ATK 16'},{id:'kira',name:'Kira',role:'Flame Mage',emoji:'🔥',cost:125,color:'#ff9d87',range:2.25,damage:33,rate:1.35,desc:'Splash · heavy burst',stats:'RANGE 2  ·  ATK 33'},{id:'yuki',name:'Yuki',role:'Frost Guard',emoji:'❄️',cost:105,color:'#b7a5ff',range:2.4,damage:11,rate:.5,slow:true,desc:'Rapid · slows enemies',stats:'RANGE 2  ·  SLOWS'}];
const stages=[{name:'Moonlit Pass',desc:'The first rift has opened. Hold the line, Starwarden.',chapter:'01 · THE MOONLIT PASS'},{name:'Sakura Crossing',desc:'A crimson tide spills through the shrine gates.',chapter:'02 · SAKURA CROSSING'},{name:'Celestial Ruins',desc:'Ancient stars awaken beneath the broken spires.',chapter:'03 · CELESTIAL RUINS'}];
const path=[[0,5.6],[2.5,5.6],[2.5,3.8],[5.3,3.8],[5.3,2],[8,2],[8,5.6],[10,5.6]],slots=[[1,4.55],[3.55,5.05],[3.5,3.15],[6.25,3.05],[6.25,1.35],[8.8,2.85],[8.85,5.05]];
let state={gold:260,lives:20,stage:0,wave:0,mode:'story',selected:null,towers:[],enemies:[],shots:[],particles:[],running:false,spawn:0,toSpawn:0,spawnTimer:0,elapsed:0,speed:1,gameOver:false,completed:false};
let W=0,H=0,dpr=1,scale=1,origin={x:0,y:0},toastTimer;
function proj(x,y,z=0){return{x:origin.x+(x-y)*scale*.86,y:origin.y+(x+y)*scale*.43-z*scale}}
function fit(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.min(W/13,H/9.3);origin={x:W*.48,y:H*.19};}
new ResizeObserver(fit).observe(canvas);fit();
const rnd=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function pathPoint(t){let lens=[],total=0;for(let i=1;i<path.length;i++){let d=Math.hypot(path[i][0]-path[i-1][0],path[i][1]-path[i-1][1]);lens.push(d);total+=d}let d=t*total;for(let i=0;i<lens.length;i++){if(d<=lens[i]){let f=d/lens[i];return{x:path[i][0]+(path[i+1][0]-path[i][0])*f,y:path[i][1]+(path[i+1][1]-path[i][1])*f}}d-=lens[i]}return{x:10,y:5.6}}
function pathLength(){return path.slice(1).reduce((a,p,i)=>a+Math.hypot(p[0]-path[i][0],p[1]-path[i][1]),0)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1700)}
function circle(x,y,r,fill,alpha=1){ctx.globalAlpha=alpha;ctx.fillStyle=fill;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
function polygon(points,fill,stroke=null){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function linePath(points,width,color){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.lineJoin='round';ctx.lineCap='round';ctx.lineWidth=width;ctx.strokeStyle=color;ctx.stroke()}
function terrain(){
// sky and distant nebula
let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1c2440');g.addColorStop(.55,'#252745');g.addColorStop(1,'#151a30');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
for(let i=0;i<66;i++){let x=(i*173.7+31)%W,y=(i*97.3+13)%(H*.63);circle(x,y,(i%4===0?1.3:.7),i%3===0?'#d7c7ff':'#a7d8ff',.16+Math.sin(state.elapsed*1.6+i)*.08)}
// floating island silhouette
let corners=[[0,1.6],[2.6,.6],[5.4,.85],[8.1,.4],[10.4,1.4],[10.4,6.6],[8.5,7.5],[5,7.2],[1.3,7.7],[-.8,6.2]].map(p=>proj(p[0],p[1]));polygon(corners,'#303752','#566080');
let inner=[[.1,1.7],[2.5,.9],[5.4,1.15],[8,.72],[10.1,1.65],[10.1,6.35],[8.4,7.1],[5,6.95],[1.4,7.3],[-.5,6]].map(p=>proj(p[0],p[1]));polygon(inner,'#414765');
// distant crystal decorations
for(const [x,y,s] of [[.35,2.1,1],[9.55,1.25,.9],[1.15,6.4,.7],[9.35,6.3,1]]){let p=proj(x,y);ctx.save();ctx.translate(p.x,p.y);ctx.globalAlpha=.6;ctx.fillStyle='#8feaff';ctx.shadowColor='#66ddff';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(0,-12*s);ctx.lineTo(5*s,-2*s);ctx.lineTo(1*s,8*s);ctx.lineTo(-4*s,0);ctx.closePath();ctx.fill();ctx.restore()}
// road
const pts=path.map(p=>proj(p[0],p[1]));linePath(pts,scale*1.17,'#292d48');linePath(pts,scale*.97,'#b49a7d');linePath(pts,scale*.89,'#dfc99e');linePath(pts,scale*.76,'#c8af8b');
ctx.setLineDash([4,8]);linePath(pts,1,'#fff6d866');ctx.setLineDash([]);
// tiny road cross bands
for(let i=0;i<25;i++){let t=i/25,p=pathPoint(t),q=proj(p.x,p.y);ctx.strokeStyle='#6d5f6070';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x-scale*.29,q.y-scale*.15);ctx.lineTo(q.x+scale*.29,q.y+scale*.15);ctx.stroke()}
// gate / portal endpoint
let gate=proj(10,5.6);ctx.save();ctx.translate(gate.x,gate.y);ctx.shadowColor='#ff6cb7';ctx.shadowBlur=20;ctx.strokeStyle='#ff9dcc';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(0,-scale*.16,scale*.32,scale*.56,0,Math.PI,0);ctx.stroke();ctx.fillStyle='#ff8fc53a';ctx.beginPath();ctx.ellipse(0,-scale*.14,scale*.25,scale*.38,0,Math.PI,0);ctx.fill();ctx.restore();
// spawn gate
let start=proj(0,5.6);circle(start.x,start.y,scale*.15,'#91eaff',.75);circle(start.x,start.y,scale*.08,'#e1fdff');
}
function drawSlot(i){let [x,y]=slots[i],p=proj(x,y);let occupied=state.towers.find(t=>t.slot===i);let selected=state.selected;ctx.save();ctx.translate(p.x,p.y);let pulse=1+Math.sin(state.elapsed*3+i)*.08;ctx.globalAlpha=occupied?.8:.55;ctx.fillStyle=occupied?occupied.color:(selected?units.find(u=>u.id===selected).color:'#b8a8ff');ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=occupied?14:10;ctx.beginPath();ctx.ellipse(0,2,scale*.27*pulse,scale*.13*pulse,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.globalAlpha=.85;ctx.strokeStyle='#f1eaff';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(0,-scale*.16);ctx.lineTo(scale*.11,0);ctx.lineTo(0,scale*.16);ctx.lineTo(-scale*.11,0);ctx.closePath();ctx.stroke();if(!occupied){ctx.fillStyle='#fff';ctx.font=`${Math.max(9,scale*.2)}px sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(selected?'+':'✦',0,0)}ctx.restore()}
function drawTower(t){let p=proj(t.x,t.y),c=t.color;ctx.save();ctx.translate(p.x,p.y);circle(0,2,scale*.22,c,.13);ctx.fillStyle='#1c2038';ctx.beginPath();ctx.ellipse(0,3,scale*.17,scale*.09,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c;ctx.shadowColor=c;ctx.shadowBlur=12;ctx.beginPath();ctx.ellipse(0,-scale*.06,scale*.115,scale*.17,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#f7d8d1';ctx.beginPath();ctx.arc(0,-scale*.26,scale*.12,0,Math.PI*2);ctx.fill();ctx.fillStyle=t.id==='mira'?'#392c53':t.id==='kira'?'#833d4c':'#3c3972';ctx.beginPath();ctx.arc(0,-scale*.29,scale*.125,Math.PI,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-scale*.1,-scale*.31);ctx.lineTo(-scale*.18,-scale*.48);ctx.lineTo(-scale*.01,-scale*.38);ctx.fill();ctx.fillStyle='#2d2540';circle(-scale*.04,-scale*.26,scale*.015,'#463351');circle(scale*.045,-scale*.26,scale*.015,'#463351');if(t.level>1){circle(scale*.14,-scale*.3,scale*.045,'#ffdb8d');ctx.fillStyle='#fff';ctx.font=`${scale*.12}px sans-serif`;ctx.textAlign='center';ctx.fillText('★',scale*.14,-scale*.27)}ctx.restore()}
