}
function spawnEnemy(){let n=state.wave,elite=state.mode==='endless'&&n%5===0;let hp=(52+n*17)*(elite?3:1);state.enemies.push({id:Math.random()*1e6,t:0,hp,max:hp,speed:elite?.022:.032+Math.min(n*.0008,.018),color:elite?'#ff648f':(['#d878bd','#ee80a7','#a970c6'][Math.floor(Math.random()*3)]),reward:elite?35:10,slow:0});}
function beginWave(){if(state.gameOver||state.completed)return;if(state.running){state.speed=state.speed===1?2:1;toast(state.speed===2?'Speed x2':'Speed x1');return}if(state.wave>=5&&state.mode==='story'){nextChapter();return}state.wave++;state.toSpawn=state.mode==='story'?6+state.wave*2:8+Math.min(state.wave*2,36);state.spawn=0;state.spawnTimer=.15;state.running=true;state.speed=1;$('#waveStatus').textContent='INCOMING';$('#waveNum').textContent=state.wave;$('#waveTotal').textContent=state.mode==='story'?'/ 5':'/ ∞';$('#launchSub').textContent='WAVE IN PROGRESS · SPEED ×1';$('#launchBtn b').textContent='SPEED UP';$('#bonus').textContent='+'+(30+state.wave*10);updateUI();toast(`Wave ${state.wave} incoming!`)}
function update(dt){state.elapsed+=dt;if(state.running&&!state.gameOver){dt*=state.speed;state.spawnTimer-=dt;if(state.spawn<state.toSpawn&&state.spawnTimer<=0){spawnEnemy();state.spawn++;state.spawnTimer=Math.max(.35,1.05-state.wave*.035)}for(const e of state.enemies){if(e.slow>0)e.slow=Math.max(0,e.slow-dt);e.t+=e.speed*dt*(e.slow>0?.48:1);let p=pathPoint(e.t);e.x=p.x;e.y=p.y;if(e.t>=1){e.hp=0;state.lives--;toast('The Astral Core is under attack!');}}}
